INSERT INTO novels (id, title, slug, author_name, category_id, synopsis, status, is_published, view_count, created_by, created_at, updated_at) VALUES
(1, 'แสงจันทร์บนหลังคาเมือง', 'moonlight-roof', 'พิมพ์ดาว ศรีอุบล', 1, 'ในเมืองที่หลังคาบ้านจำชื่อของคนที่เคยยืนมองพระจันทร์ได้ มิน เด็กส่งของเริ่มได้ยินกระเบื้องกระซิบ เสียงนั้นพาเธอไปยังร้านน้ำชาที่เปิดเฉพาะตีสาม และแผนที่ที่ไม่มีใครยอมรับว่าเป็นคนวาด', 'ongoing', 1, 1280, 1, '2026-09-01 20:00:00', '2026-11-04 21:10:00'),
(2, 'จดหมายที่ไม่เคยส่ง', 'unsent-letter', 'นภา วรรณศิลป์', 2, 'หลังย้ายบ้าน ปลาพบกล่องไม้ใต้เตียงเก่า ข้างในคือจดหมายหลายสิบฉบับที่เขียนถึงคนคนเดียวแต่ไม่เคยถึงมือ เธอเริ่มตามที่อยู่สุดท้ายที่หมึกยังไม่ซีด', 'completed', 1, 980, 1, '2026-07-12 10:00:00', '2026-08-02 11:20:00'),
(3, 'ห้องที่ไม่มีเลข', 'room-without-number', 'ภูผา ศักดิ์สิทธิ์', 3, 'ลิฟต์ของอาคารเก่าหยุดระหว่างชั้นโดยไม่มีปุ่มให้กด นักข่าวท้องถิ่นพบรายชื่อผู้พักที่ไม่มีอยู่ในสมุดทะเบียน และห้องหนึ่งที่ไม่ปรากฏบนแปลน', 'ongoing', 1, 860, 1, '2026-09-28 18:00:00', '2026-10-20 18:40:00'),
(4, 'ดาวดวงสุดท้ายของท่าเรือ', 'last-star', 'อรุณ เมฆา', 4, 'เมื่อไฟนำทางของท่าเรือวงโคจรรอบนอกดับลง ช่างสื่อสารคนเดียวต้องตัดสินใจว่าจะส่งข้อความขอความช่วยเหลือ หรือเก็บความลับของดาวที่กำลังมอดไว้กับเรือ', 'completed', 1, 1540, 1, '2026-08-20 15:00:00', '2026-09-18 16:05:00'),
(5, 'ถนนเกลือ', 'salt-road', 'ทะเล แก้วมณี', 5, 'ตลาดริมทางขายทิศทางแทนสินค้า ใครจ่ายถูกจะได้ทางสั้น ใครจ่ายแพงจะได้ทางที่ยังมีคนกลับมาเล่าได้ เด็กหาบน้ำคนหนึ่งซื้อทางที่ไม่มีใครกล้าข้ามสองครั้ง', 'ongoing', 1, 430, 1, '2026-10-15 09:30:00', '2026-11-01 19:00:00'),
(6, 'บ่อน้ำหลังบ้าน', 'well-behind-house', 'ม่านหมอก', 6, 'เชือกที่หย่อนลงบ่อหลังบ้านสั้นลงทุกคืน ทั้งที่ไม่มีใครตัดมัน ครอบครัวที่ย้ายเข้าบ้านเก่าต้องเลือกว่าจะปิดฝา หรือจะฟังสิ่งที่ลอยขึ้นมากับน้ำ', 'completed', 1, 2100, 1, '2026-09-02 21:00:00', '2026-10-11 22:15:00'),
(7, 'สมุดโน้ตของคนขายแผนที่', 'map-seller-notebook', 'พิมพ์ดาว ศรีอุบล', 7, 'ฉบับร่างที่ยังไม่เปิดให้ผู้อ่าน เป็นบันทึกของคนขายแผนที่ที่อ้างว่าทางบางสายมีอยู่เฉพาะตอนฝนตก', 'ongoing', 0, 12, 1, '2026-11-02 08:00:00', '2026-11-03 08:00:00');

INSERT INTO chapters (novel_id, chapter_number, title, content, is_published, view_count, created_at, updated_at) VALUES
(1, 1, 'หลังคาที่จำชื่อคน', 'เมื่อฝนหยุด เมืองนี้จะเงียบพอให้ได้ยินกระเบื้องคุยกัน\n\nมินเดินส่งของชิ้นสุดท้ายขึ้นบันไดเหล็กข้างตึกแถว กล่องในมืออุ่นเพราะข้าวที่แม่ค้าฝากให้ลูกชาย เธอคุ้นทางนี้จนไม่ต้องมองขั้น แต่คืนนั้นกระเบื้องที่ยังไม่แห้งเอ่ยชื่อเธอออกมา\n\nมิน เสียงเบาเหมือนคนพูดจากอีกฝั่งของผ้าม่าน เมื่อก่อนเธอเคยยืนตรงนี้กับคนที่ใส่เสื้อสีคราม\n\nมินหยุดกึก ลมบนหลังคาไม่แรงพอจะทำเสียงแบบนั้น เธอมองลงไปที่ตรอก ไฟร้านขายของชำดับไปแล้ว เหลือแต่หลอดไฟปลายซอยที่กระพริบช้า ๆ\n\nฉันไม่รู้จักคนเสื้อสีคราม เธอตอบทั้งที่ไม่แน่ใจว่าควรตอบสิ่งที่ไม่มีปาก\n\nกระเบื้องหัวเราะสั้น ๆ หลังคาจำได้แม้คนจะลืม ถ้าเธออยากรู้ ให้ไปที่ร้านน้ำชาที่เปิดตอนตีสาม ขอชาที่ไม่มีชื่อ\n\nก่อนที่มินจะถามต่อ เสียงก็หายไปกับกลิ่นดินเปียก เธอส่งข้าวเสร็จแล้วนั่งบนขั้นบันไดนานกว่าทุกคืน เสื้อสีครามผุดขึ้นเป็นภาพราง ๆ ของคนที่ยืนชี้พระจันทร์ แล้วบอกว่าเมืองนี้กว้างกว่าแผนที่\n\nเธอไม่รู้ว่าคนคนนั้นคือใคร แต่เธอรู้ว่าตีสามคืนนี้เธอจะไม่กลับบ้านทันที', 1, 320, '2026-09-01 20:10:00', '2026-09-01 20:10:00'),
(1, 2, 'ร้านน้ำชาที่เปิดตอนตีสาม', 'ร้านไม่มีป้าย อยู่ในซอกตึกที่กลางวันมีแต่รถเข็นจอดซ้อนกัน ประตูไม้เปิดออกเองตอนเข็มนาฬิกาของมินขึ้นเลขสาม\n\nข้างในมีโต๊ะเดียว กับกาน้ำที่ส่งเสียงเหมือนฝนยังไม่หยุดตก คนชงชาไม่ถามชื่อเธอ เขาวางถ้วยเปล่าไว้ตรงหน้าแล้วพูดว่า ชาที่ไม่มีชื่อต้องให้คนดื่มตั้งชื่อเอง\n\nมินมองใบชาที่ยังไม่ถูกใส่ลงไป แล้วพูดคำแรกที่ผุดขึ้น คราม\n\nน้ำในถ้วยเปลี่ยนสีช้า ๆ ไม่ใช่สีของชา แต่เป็นสีของเสื้อที่หลังคาเพิ่งเอ่ยถึง บนผิวน้ำมีเงาของทางเดินบนหลังคา เป็นเส้นที่เธอไม่เคยเดิน\n\nคนชงชายิ้มบาง ๆ เมืองนี้เก็บความทรงจำไว้บนที่สูง เพราะที่ต่ำมีคนเดินทับจนลืม ถ้าเธอตามเส้นนั้นไป จะเจอแผนที่ที่เขียนด้วยเถ้า อย่าเป่ามัน ไม่งั้นทางจะปลิว\n\nมินดื่มจนถ้วยว่าง รสชาติไม่หวานไม่ขม เหมือนน้ำฝนที่เพิ่งแตะฝุ่น เธอวางเหรียญไว้บนโต๊ะ แต่คนชงชาส่ายหน้า ค่าของชาที่ไม่มีชื่อคือคำถามหนึ่งคำ และเธอใช้มันไปแล้ว\n\nตอนออกจากร้าน ท้องฟ้าเริ่มขาว เส้นบนผิวน้ำยังติดอยู่ในหัวเธอเหมือนแผนที่ที่ยังไม่ยอมถูกพับ', 1, 210, '2026-10-02 21:00:00', '2026-10-02 21:00:00'),
(1, 3, 'แผนที่ที่เขียนด้วยเถ้า', 'มินกลับขึ้นหลังคาตอนพระอาทิตย์ยังไม่ร้อน กระเบื้องเงียบกว่าเมื่อคืน แต่เถ้าบาง ๆ เรียงตัวเป็นเส้นจากบันไดไปยังแทงก์น้ำเก่า\n\nเธอเดินตามโดยไม่เป่า ไม่แม้แต่จะหายใจแรง เมื่อถึงแทงก์น้ำ เส้นเถ้าม้วนตัวเป็นวง กลางวงมีชื่อที่เธอเพิ่งนึกออกว่าเคยได้ยินจากแม่\n\nชื่อนั้นเป็นของลุงที่จากเมืองไปตั้งแต่เธอยังไม่เข้าโรงเรียน แม่บอกว่าเขาเป็นคนซ่อมหลังคา และไม่ชอบให้ใครลืมทางกลับบ้าน\n\nใต้ชื่อมีประโยคสั้น ๆ เขียนด้วยเถ้าเช่นกัน ถ้าจำทางได้ จงเปิดร้านให้คนที่ยังหลง\n\nมินนั่งลง ลมอ่อนพอที่จะไม่พัดเถ้ากระจัดกระจาย เธอเข้าใจแล้วว่าเสื้อสีครามไม่ใช่คนแปลกหน้า และร้านน้ำชาที่เปิดตีสามอาจไม่ได้เปิดเอง\n\nเธอเก็บเถ้าใส่ซองกระดาษอย่างระมัดระวัง แล้วนำกลับไปให้แม่ดู แม่นิ่งนานก่อนพูดว่า ถนนบนดินเปลี่ยนได้ทุกปี แต่หลังคายังจำคนที่เคยยืนมองจันทร์\n\nคืนนั้นมินไม่ได้ขึ้นไปฟังกระเบื้อง เธอเปิดหน้าต่าง ปล่อยให้แสงจันทร์ตกบนซองเถ้า แล้วเขียนชื่อร้านที่ยังไม่มีป้ายลงในสมุดส่งของ เป็นชื่อที่เธอจะใช้เมื่อถึงเวลาเปิดประตูให้คนอื่น', 1, 140, '2026-11-04 21:10:00', '2026-11-04 21:10:00'),
(2, 1, 'กล่องไม้ใต้เตียง', 'บ้านหลังใหม่มีกลิ่นสีและกล่องกระดาษ ปลาเปิดห้องนอนเป็นห้องสุดท้าย เพราะเตียงเก่าที่มากับบ้านหนักเกินกว่าจะขยับคนเดียว\n\nตอนก้มเก็บเหรียญที่กลิ้งใต้เตียง มือเธอแตะไม้ที่เรียบผิดกับพื้นปูน เป็นกล่องแบนผูกด้วยเชือกฝ้าย ไม่มีกุญแจ\n\nข้างในเป็นจดหมายที่ยังไม่ติดแสตมป์ ทุกฉบับขึ้นต้นด้วยชื่อเดียวกัน และทุกฉบับลงท้ายด้วยประโยคที่ยังไม่จบ ฉันจะส่งเมื่อพร้อม แต่ดูเหมือนคนเขียนไม่เคยพร้อมสักครั้ง\n\nปลาอ่านจนฟ้ามืด เรื่องในจดหมายไม่ใช่นิยายรักที่หวานจนลืมเมือง มันเป็นบันทึกของคนสองคนที่เว้นระยะด้วยงาน ด้วยรถทัวร์ และด้วยคำที่กลัวจะถูกอ่านผิด\n\nฉบับล่าสุดมีที่อยู่บรรทัดเดียว เขียนด้วยหมึกที่ยังเข้มกว่าฉบับอื่น อยู่ท้ายซอยตลาดเช้า บ้านรั้วขาว ถ้ายังมีกระดิ่งอยู่\n\nปลาวางจดหมายกลับลงกล่องอย่างเป็นระเบียบ เธอไม่รู้ว่าควรส่งสิ่งที่เจ้าของไม่ได้ส่ง หรือควรปล่อยให้มันเป็นความลับของบ้าน แต่ชื่อนั้นทำให้เธอนอนไม่หลับ', 1, 260, '2026-07-14 19:00:00', '2026-07-14 19:00:00'),
(2, 2, 'ที่อยู่สุดท้าย', 'เช้าวันอาทิตย์ ปลาเดินไปตลาดพร้อมกล่องไม้ กระดิ่งที่รั้วขาวยังอยู่ และยังดังเมื่อเธอไม่กล้าเคาะประตู\n\nผู้หญิงสูงวัยเปิดประตูออกมา แววตาหยุดที่กล่องก่อนจะหยุดที่หน้าปลา เธอไม่ถามว่าปลาเป็นใคร เธอถามแค่ว่าเจอมันใต้เตียงใช่หรือไม่\n\nปลาพยักหน้า แล้วเล่าเท่าที่จำเป็น ไม่ได้อ่านทุกฉบับให้ฟัง ผู้อาวุโสยิ้มเหมือนคนที่รอของช้า แต่ไม่โกรธที่ของมาถึงช้า\n\nเขาเขียนไว้ทุกปีในวันเดียวกัน หญิงชรากล่าว แล้วไม่เคยเดินมาถึงรั้วนี้ เพราะคิดว่าฉันย้ายไปแล้ว ความจริงฉันอยู่มาตลอด แค่เปลี่ยนสีประตู\n\nเธอรับกล่องไว้ด้วยสองมือ แล้วชวนปลาดื่มน้ำใบเตย บนโต๊ะมีรูปของชายที่ยิ้มบาง เสื้อเชิ้ตขาว ดินสอเหน็บกระเป๋า เป็นคนเดียวกับลายมือในจดหมาย\n\nก่อนจาก หญิงชราให้ปลาเก็บซองเปล่าหนึ่งใบ เผื่อวันหนึ่งเธอมีคำที่ยังไม่กล้าส่ง จะได้รู้ว่าที่อยู่บางแห่งรอได้นานกว่าที่คนเขียนคิด\n\nปลาเดินกลับบ้านใหม่โดยไม่รู้สึกว่ามันใหม่เกินไปอีกต่อไป ใต้เตียงว่างแล้ว แต่ในลิ้นชักมีซองเปล่าหนึ่งซอง เธอเขียนชื่อคนที่อยากขอบคุณลงไป แล้วครั้งนี้เธอเดินออกไปส่งเอง', 1, 240, '2026-08-02 11:20:00', '2026-08-02 11:20:00'),
(3, 1, 'ลิฟต์หยุดระหว่างชั้น', 'อาคารศิลาทองมีแปดชั้นบนแผ่นป้าย แต่ลิฟต์ที่นักข่าวชื่อถิ่นขึ้นไปหยุดนิ่งระหว่างห้ากับหก โดยไม่มีเลขห้าจุดห้าบนปุ่ม\n\nไฟในห้องลิฟต์ไม่ดับ มีเสียงเครื่องปรับอากาศเหมือนอาคารยังทำงานปกติ ถิ่นกดทุกปุ่มแล้วไม่มีปุ่มไหนยอมรับนิ้ว\n\nประตูเปิดออกเองไปยังทางเดินที่พรมยังใหม่ แต่ไม่มีเลขห้องบนวงกบ มีเพียงประตูไม้สีเข้มบานเดียว และแผ่นโลหะที่ถูกถอดออกจนเหลือคราบกาว\n\nถิ่นจดบันทึกตามนิสัยนักข่าวท้องถิ่น เวลา สีพรม จำนวนไฟ และกลิ่นที่เหมือนกระดาษเก่าเปียกฝน เขายังไม่เคาะประตู เพราะข่าวที่ดีเริ่มจากสิ่งที่คนอื่นมองข้าม\n\nสักครู่ประตูลิฟต์ปิด แล้วเปิดอีกครั้งที่ชั้นล่างเหมือนไม่มีอะไรเกิด พนักงานเคาน์เตอร์บอกว่าลิฟต์ตัวนี้ไม่เคยหยุดระหว่างชั้น และอาคารไม่มีห้องที่ไม่มีเลข\n\nถิ่นยิ้มรับ แล้วขอสมุดผู้มาติดต่อย้อนหลังสามเดือน ชื่อหนึ่งโผล่ทุกวันศุกร์โดยไม่มีห้องปลายทาง เขาถ่ายรูปหน้ากระดาษไว้ ก่อนพนักงานจะพลิกสมุดปิด', 1, 190, '2026-09-28 18:20:00', '2026-09-28 18:20:00'),
(3, 2, 'รายชื่อที่ไม่มีในสมุด', 'ชื่อในสมุดคือ ภารต แต่ไม่มีนามสกุล ไม่มีเบอร์ และไม่มีคนในอาคารที่รับว่าเคยเจอเขา\n\nถิ่นเดินถามร้านกาแฟตรงข้าม บาริสต้าจำชายที่สั่งกาแฟดำทุกวันศุกร์ได้ เขาไม่ขึ้นลิฟต์ต่อหน้าใคร เขายืนรอจนประตูเปิดเองทั้งที่ไม่มีคนกดเรียก\n\nคืนวันศุกร์ ถิ่นกลับไปที่อาคารโดยไม่พกกล้องใหญ่ เขากดชั้นห้า แล้วกดชั้นหกซ้อนกันแบบที่ไม่ได้เขียนในคู่มือใด ประตูเปิดที่ทางเดินพรมใหม่อีกครั้ง\n\nคราวนี้ประตูไม้แง้มไว้ ข้างในไม่มีเฟอร์นิเจอร์ มีแต่ตะปูเรียงเป็นแถวบนฝาผนัง และกระดาษโน้ตที่เขียนว่า ห้องนี้มีไว้สำหรับข่าวที่ยังไม่มีคนเชื่อ\n\nถิ่นอ่านแล้วขนลุก ไม่ใช่เพราะกลัวผี แต่เพราะลายมือเหมือนลายมือของเขาเองตอนรีบจด เขาไม่ได้เขียนโน้ตนั้น และเขาก็ยังไม่พร้อมจะเชื่อว่าอาคารช่วยจดข่าวให้\n\nก่อนประตูลิฟต์จะเรียกเขากลับ ถิ่นถ่ายรูปโน้ตด้วยโทรศัพท์ ภาพติดทุกอย่างยกเว้นตัวอักษร เหลือแต่ตะปูบนฝาผนังว่าง เขาออกมาที่ชั้นล่างพร้อมคำถามใหม่ ซึ่งดีกว่างานข่าวที่รู้คำตอบตั้งแต่วันแรก', 1, 150, '2026-10-20 18:40:00', '2026-10-20 18:40:00'),
(4, 1, 'ไฟนำทางที่ดับ', 'ท่าเรือวงโคจรรอบนอกมีไฟนำทางสามดวง สองดวงแรกดับในคืนเดียวกัน ดวงที่สามกะพริบเหมือนคนกำลังตัดสินใจ\n\nช่างสื่อสารชื่อวาดอยู่คนเดียวบนสถานี เพราะรอบส่งกำลังคนถูกเลื่อนออกไปอีกสิบวัน เขาตรวจสายสัญญาณจนนิ้วชา แล้วพบว่าไฟไม่ได้เสีย มันถูกสั่งให้เงียบจากศูนย์ที่ไม่มีอยู่ในแผนที่ปัจจุบัน\n\nบนจอมีข้อความเก่าค้างอยู่ ดาวดวงนั้นไม่ควรมีเรือไปจอด ถ้ามีใครขอท่า จงบอกว่าปิดซ่อม\n\nวาดไม่ชอบคำสั่งที่ไม่มีชื่อคนสั่ง เขาเปิดคลังบันทึก แล้วพบภาพดาวดวงหนึ่งที่หายไปจากแผนที่นำทางรอบล่าสุด ทั้งที่แสงของมันยังเข้ากล้องได้จาง ๆ\n\nเรือลำเล็กเรียกเข้ามาด้วยรหัสเก่า ขอจอดเพราะออกซิเจนเหลือไม่ถึงทางกลับ วาดมองไฟดวงสุดท้ายที่ยังกะพริบ ถ้าเขาเปิดท่า เขาอาจขัดคำสั่ง ถ้าเขาปิดท่า เขาจะมีชื่อของคนบนเรืออยู่ในหัวไปอีกนาน\n\nเขาวางมือบนสวิตช์ แล้วเลือกที่จะตอบด้วยความจริงเท่าที่รู้ ท่ายังมีไฟอยู่หนึ่งดวง เข้ามาได้ แต่จงเตรียมคำอธิบายให้ดีกว่าของผม', 1, 410, '2026-08-22 16:00:00', '2026-08-22 16:00:00'),
(4, 2, 'ข้อความจากวงโคจร', 'เรือลำเล็กจอดโดยใช้ไฟดวงเดียวเป็นแนว นักบินเป็นคนแก่ที่เคยทำงานบนสถานีนี้สมัยที่ดาวยังมีชื่อในแผนที่\n\nเขาเล่าว่าดาวไม่ได้มอดเอง มีคนปิดชื่อของมันเพื่อไม่ให้ใครไปเก็บแร่ที่ทำให้เครื่องสื่อสารของทั้งวงโคจรเงียบ ไฟนำทางถูกดับเพื่อให้ทางดูเหมือนไม่มีอยู่\n\nวาดฟังโดยไม่ขัด หลักฐานในคลังบันทึกพอจะทำให้เรื่องนี้ไม่ใช่แค่ตำนานของคนแก่ เขาส่งข้อความถึงศูนย์ด้วยถ้อยคำเรียบ ๆ ว่ามีเรือขอความช่วยเหลือ และมีข้อมูลว่าการปิดไฟอาจเป็นคำสั่งที่ไม่ได้บันทึกในระบบปัจจุบัน\n\nคำตอบกลับมาช้า แต่มาในรูปที่เขาหวัง คือให้เปิดไฟทั้งสามดวงและรับคนเจ็บก่อน แล้วค่อยเปิดการสอบสวนคำสั่งเก่า\n\nนักบินยื่นชิปข้อมูลให้ก่อนลงนอน ข้างในเป็นแผนที่ดาวที่ยังมีชื่อ วาดคัดลอกไฟล์ไม่ได้ เพราะเครื่องอ่านของสถานีปฏิเสธไฟล์ที่ไม่มีลายเซ็นรุ่นใหม่ เขาจึงจดชื่อดาวลงสมุดกระดาษด้วยลายมือ\n\nตอนไฟทั้งสามดวงสว่างพร้อมกัน ท่าเรือดูเหมือนกลับมาอยู่ในโลกอีกครั้ง วาดยืนมองวงโคจรแล้วคิดว่า ความลับที่เก็บไว้นานที่สุดมักเริ่มจากคนที่เชื่อว่าการเงียบคือการปกป้อง แต่การเงียบก็ทำให้เรือบางลำหลงทางเหมือนกัน', 1, 360, '2026-09-18 16:05:00', '2026-09-18 16:05:00'),
(5, 1, 'ตลาดที่ขายทิศทาง', 'ตลาดบนถนนเกลือไม่ขายปลา ไม่ขายผ้า และไม่ขายน้ำ แม้จะมีเด็กหาบน้ำเดินผ่านทุกเช้า สิ่งที่แขวนอยู่บนร้านคือป้ายทิศ เหนือ ใต้ ทางกลับ และทางที่ยังไม่มีชื่อ\n\nน้ำ เด็กหาบถังสองใบ หยุดฟังพ่อค้าบอกราคา ทางสั้นราคาถูก แต่คนที่เดินทางนั้นมักไม่กลับมาเล่าว่าเจออะไร ทางแพงยาวกว่า และมีเรื่องให้เล่าจนคุ้มกับน้ำที่หกไประหว่างทาง\n\nน้ำไม่มีเงินมาก เธอมีเกลือหนึ่งถุงที่ได้มาแทนค่าจ้าง พ่อค้ามองถุงแล้วพยักหน้า เกลือซื้อได้ทางที่ข้ามได้ครั้งเดียว ถ้าข้ามแล้วยังอยากกลับ ต้องหาเกลือใหม่จากอีกฝั่ง\n\nเธอถามว่าอีกฝั่งมีอะไร พ่อค้าตอบว่ามีสะพานที่จำหน้าคนเดิน และบ่อที่แลกเรื่องเล่ากับน้ำจืด ซึ่งฟังแล้วไม่น่าเชื่อ แต่ตลาดนี้ไม่รับประกันความน่าเชื่ออยู่แล้ว\n\nน้ำส่งถังให้ลูกค้าคนสุดท้าย แล้วกลับมายื่นถุงเกลือ ป้ายทางถูกมัดด้วยเชือกแดงสั้น ๆ พ่อค้ากำชับว่า อย่าเดินย้อนกลับบนเส้นเดิม ถนนเกลือไม่ชอบคนที่เปลี่ยนใจกลางทาง\n\nเธอแขวนป้ายไว้ที่คานหาบ แล้วออกจากตลาดตอนแดดยังไม่เอียง คราบเกลือบนแขนเริ่มแสบ แต่เธอคิดว่าทางที่ข้ามได้ครั้งเดียวอาจดีกว่าทางที่เดินทุกวันแล้วยังไม่ถึงไหน', 1, 120, '2026-10-16 09:40:00', '2026-10-16 09:40:00'),
(5, 2, 'สะพานที่ข้ามได้ครั้งเดียว', 'สะพานไม่ยาวอย่างที่ป้ายทำให้คิด มันพาดคลองน้ำใสที่มองเห็นพื้นหินได้ทุกก้อน ปัญหาคือพอเท้าข้างหนึ่งของน้ำแตะไม้แผ่นแรก อีกฝั่งก็เลื่อนห่างออกไปอีกนิด\n\nเธอจำคำพ่อค้าได้ จึงไม่ถอย เดินต่อแม้หาบจะหนักและเชือกแดงที่ป้ายเริ่มคลาย กลางสะพานมีคนนั่งห้อยเท้า เป็นเด็กอายุใกล้เคียงกัน ถือถุงเกลือที่ดูเก่ากว่าของเธอ\n\nข้ามให้จบในครั้งเดียว เด็กคนนั้นพูด ฉันถอยกลับเมื่อวาน วันนี้สะพานจำหน้าฉันแล้วไม่ยอมให้ผ่าน\n\nน้ำวางถังลง แล้วแบ่งน้ำให้เด็กครึ่งแก้ว เด็กยิ้มแล้วบอกทางลัดที่ไม่มีบนป้าย ให้มองก้อนหินก้อนที่สาม แล้วก้าวตามจังหวะที่คลองกระเพื่อม ไม่ใช่ตามความยาวของแผ่นไม้\n\nน้ำยกหาบขึ้นใหม่ คราวนี้เธอไม่นับแผ่น เธอนับคลื่น เมื่อเท้าแตะฝั่ง ป้ายที่คอหาบหลุดเป็นเกลือผง ทางนั้นใช้หมดแล้วจริง ๆ\n\nเด็กบนสะพานโบกมือ แล้วค่อย ๆ จางไปกับแสงเหมือนคนที่ถูกทางจำไว้นานเกินไป น้ำไม่ร้องเรียกกลับ เธอเติมน้ำจากบ่อที่แลกกับเรื่องเล่า เล่าเรื่องตลาดให้บ่อฟังจนถังเต็ม แล้วเดินต่อด้วยเส้นทางที่ยังไม่มีป้าย แต่ครั้งนี้เธอรู้ว่าการไม่ถอยคือค่าผ่านทาง', 1, 90, '2026-11-01 19:00:00', '2026-11-01 19:00:00'),
(6, 1, 'เชือกที่สั้นลงทุกคืน', 'บ้านหลังเก่ามีบ่อน้ำอยู่หลังครัว ฝาไม้หนักพอที่เด็กจะเปิดคนเดียวไม่ได้ แต่เชือกที่ผูกกับถังยังใหม่ เพราะเจ้าของเดิมเพิ่งเปลี่ยนมันก่อนย้ายออก\n\nคืนแรกที่ครอบครัวอยู่กันครบ แม่วัดเชือกด้วยช่วงแขนได้แปดช่วง เช้าวันต่อมาเหลือเจ็ด ทั้งที่ถังยังอยู่ที่ปากบ่อ และไม่มีรอยตัด\n\nพ่อบอกว่าเชือกหดเมื่ออากาศเย็น แม่ไม่เถียง แต่เธอผูกปมไว้ที่ช่วงที่เจ็ด ปมนั้นหายไปในคืนถัดมา พร้อมกับเชือกที่สั้นลงอีก\n\nลูกสาวคนโตชื่อเดือนเริ่มจดความยาวทุกเช้าลงสมุดการบ้าน วันที่เชือกเหลือสี่ช่วง เธอได้ยินเสียงน้ำกระเพื่อมทั้งที่ไม่มีลม และได้กลิ่นดินเปียกในห้องนอนที่อยู่ชั้นสอง\n\nเดือนไม่เปิดฝา เธอเอาหูแนบไม้ แล้วได้ยินคนนับช่วงเชือกย้อนกลับ จากสี่ไปห้า ราวกับมีคนข้างล่างกำลังคืนความยาวที่วันนั้นถูกยึดไป\n\nเธอเล่าให้พ่อฟังโดยไม่เติมคำว่าผี พ่อเงียบ แล้วไปซื้อฝาใหม่กับแม่กุญแจ ก่อนพระอาทิตย์ตก เชือกถูกดึงขึ้นมาทั้งเส้น มันยาวเท่าเดิมทุกช่วง รวมทั้งปมที่แม่ผูกไว้และคิดว่าหายไปแล้ว', 1, 500, '2026-09-04 21:30:00', '2026-09-04 21:30:00'),
(6, 2, 'สิ่งที่ลอยขึ้นมากับน้ำ', 'แม่กุญแจอยู่ได้สองคืน วันที่สามมันเปิดอยู่บนขั้นบันไดทั้งที่พวงกุญแจยังอยู่ในบ้าน ฝาบ่อไม่ได้ถูกงัด มันถูกวางไว้ข้าง ๆ อย่างเรียบร้อย\n\nในบ่อมีน้ำใสจนเห็นก้น และมีสมุดห่อผ้าลอยอยู่โดยไม่จม เดือนใช้ไม้เกี่ยวยกขึ้นมา ทั้งบ้านยืนดูตอนเธอคลี่ผ้า\n\nสมุดเป็นของเจ้าของเดิม เขาจดว่าบ่อนี้ไม่ได้อยากได้คน มันอยากได้เรื่องที่คนในบ้านไม่ยอมพูดให้จบ เชือกจะสั้นลงทุกครั้งที่มีประโยคค้างคา และจะคืนความยาวเมื่อมีคนอ่านเรื่องนั้นจนจบ\n\nหน้าสุดท้ายเว้นไว้ มีบรรทัดเดียวว่า ครอบครัวต่อไปโปรดเขียนให้จบ อย่าเพิ่งปิดฝา\n\nแม่กับพ่อสบตากัน เรื่องที่ค้างคาไม่ใช่เรื่องผี แต่เป็นเรื่องการย้ายบ้านที่ยังไม่ได้บอกเดือนตรง ๆ ว่าทำไมต้องจากเมืองเก่า เดือนยื่นสมุดให้ แล้วรอ\n\nคืนนั้นพวกเขาเขียนต่อจนหมึกหมด ไม่ได้เขียนสวย แต่เขียนจนจบ เช้าวันต่อมาเชือกยาวครบ ฝาปิดอยู่ได้โดยไม่มีกุญแจ และน้ำในบ่อนิ่งเหมือนบ่อทั่วไป เดือนยังจดความยาวทุกเช้าอีกเจ็ดวัน จนแน่ใจว่าบางเรื่องจบลงได้ถ้ามีคนยอมเล่าให้ครบ', 1, 470, '2026-10-11 22:15:00', '2026-10-11 22:15:00'),
(7, 1, 'ทางที่มีเฉพาะตอนฝนตก', 'คนขายแผนที่จดไว้ว่าถนนบางสายไม่ควรพิมพ์ลงกระดาษ เพราะมันมีอยู่เฉพาะตอนฝนตกหนัก และหายไปเมื่อแดดออก\n\nเขาทดลองเดินตามรอยน้ำบนถนนเกลือ แล้วพบว่าตลาดที่ขายทิศทางกับหลังคาที่จำชื่อคนอาจอยู่บนเมืองเดียวกัน เพียงแต่คนละเวลา\n\nบันทึกนี้ยังไม่ถูกตรวจ และยังไม่ควรเปิดให้ผู้อ่านจนกว่าแผนที่จะถูกเดินซ้ำอย่างน้อยหนึ่งครั้งในหน้าฝนถัดไป', 0, 3, '2026-11-03 08:00:00', '2026-11-03 08:00:00');
